const config = $('Configurar1').first().json;
const queries = $input.all().map(item => item.json);
if (!queries.length || queries[0].query_id === undefined) throw new Error('Nenhuma consulta.');
if (queries.some(q => q.missing_query_embedding) || Number(queries[0].missing_document_embeddings)>0) {
  throw new Error('Complete os embeddings de consultas e produtos antes da comparação.');
}
if (!Number.isInteger(config.top_k) || config.top_k<10 || config.top_k>100 ||
    !Number.isInteger(config.repetitions) || config.repetitions<1 ||
    !Number.isInteger(config.warmup_repetitions) || config.warmup_repetitions<0 ||
    config.full_text_weight<=0 || config.semantic_weight<=0 || config.rrf_k<=0) throw new Error('Configuração inválida.');
// Gerador com seed: mesma ordem de execução ao repetir o experimento.
let state = Number(config.seed) >>> 0;
function random() { state=(Math.imul(1664525,state)+1013904223)>>>0; return state/4294967296; }
function shuffle(values) {
  const result=[...values];
  for (let i=result.length-1;i>0;i--) { const j=Math.floor(random()*(i+1)); [result[i],result[j]]=[result[j],result[i]]; }
  return result;
}
const tasks=[];
for (let round=1;round<=config.warmup_repetitions+config.repetitions;round++) {
  const isWarmup=round<=config.warmup_repetitions;
  for (const query of shuffle(queries)) {
    for (const method of shuffle(['lexical','semantic','hybrid'])) {
      tasks.push({json:{query_id:query.query_id,method,configuration:{
        ...config,evaluator:'simple_v2',query_count:queries.length,
        repetition:round-config.warmup_repetitions,is_warmup:isWarmup,
      }}});
    }
  }
}
return tasks;

// Relatório v3: métricas binárias usam somente consultas com ao menos um Exact.
// A seleção depende dos julgamentos (exact_count > 0), NÃO dos acertos retornados.
// Consultas elegíveis sem acertos continuam na média, com valor zero.
// nDCG mantém IDCG > 0; latência e cobertura mantêm todas as consultas.
const rows = $input.all().map(item => item.json);
if (!rows.length || !rows[0].configuration) throw new Error('Nenhum resultado deste experimento.');
const config = rows[0].configuration;
const methods = ['lexical', 'semantic', 'hybrid'];
const expectedQueries = Number(config.query_count);
const expectedRepetitions = Number(config.repetitions);
if (rows.length !== expectedQueries * 3) throw new Error('Experimento incompleto ou duplicado. Execute novamente com outro experiment_name.');
const seen = new Set();
for (const row of rows) {
  const key = `${row.query_id}:${row.method}`;
  if (seen.has(key) || !methods.includes(row.method)) throw new Error('Consulta/método duplicado ou inválido.');
  seen.add(key);
  if (row.repetitions.length !== expectedRepetitions ||
      row.repetitions.some((r, i) => Number(r) !== i + 1)) throw new Error('Repetições ausentes ou duplicadas.');
  if (row.latency_samples.some(x => x === null || !Number.isFinite(Number(x)) || Number(x) < 0)) throw new Error('Latência inválida.');
}
// Cada método precisa das MESMAS consultas.
const queries = [...new Set(rows.map(r => r.query_id))];
if (queries.length !== expectedQueries || queries.some(id => methods.some(m => !seen.has(`${id}:${m}`)))) {
  throw new Error('Os três métodos precisam das mesmas consultas.');
}
const mean = values => {
  const valid = values.filter(v => v !== null && v !== undefined);
  return valid.length ? valid.reduce((a, b) => a + b, 0) / valid.length : null;
};
function percentile(values, p) {
  const sorted = [...values].sort((a, b) => a - b);
  const index = (sorted.length - 1) * p;
  const low = Math.floor(index), high = Math.ceil(index);
  return sorted[low] + (sorted[high] - sorted[low]) * (index - low);
}
function metrics(row, k) {
  const results = row.results.filter(r => Number(r.rank) <= k);
  const exact = results.filter(r => r.label === 'Exact');
  const firstExact = exact.length ? Math.min(...exact.map(r => Number(r.rank))) : null;
  const totalExact = Number(row.exact_count);
  const totalPartial = Number(row.partial_count);
  const binaryEligible = totalExact > 0;
  const grade = label => label === 'Exact' ? 2 : label === 'Partial' ? 1 : 0;
  // DCG = soma dos ganhos descontados pela posição ORIGINAL.
  const dcg = results.reduce((sum, r) => sum + (2 ** grade(r.label) - 1) / Math.log2(Number(r.rank) + 1), 0);
  // O ranking ideal usa TODOS os julgamentos da consulta.
  const ideal = [...Array(totalExact).fill(2), ...Array(totalPartial).fill(1)].slice(0, k);
  const idcg = ideal.reduce((sum, g, i) => sum + (2 ** g - 1) / Math.log2(i + 2), 0);
  const judged = results.filter(r => r.label !== null && r.label !== undefined).length;
  return {
    query_id: row.query_id, query: row.query, method: row.method, k,
    exact_count: totalExact,
    binary_eligible: binaryEligible,
    rr: binaryEligible ? (firstExact === null ? 0 : 1 / firstExact) : null,
    precision: binaryEligible ? exact.length / k : null,
    recall: binaryEligible ? exact.length / totalExact : null,
    ndcg: idcg > 0 ? dcg / idcg : null,
    hit_rate: binaryEligible ? (exact.length > 0 ? 1 : 0) : null,
    returned: results.length,
    judged_fraction_returned: results.length ? judged / results.length : null,
    unjudged: results.length - judged,
  };
}
const cutoffs = [...new Set([5, 10, Number(config.top_k)])];
const perQuery = rows.flatMap(row => cutoffs.map(k => metrics(row, k)));
const summary = [];
for (const method of methods) {
  // As repetições são usadas para latência; qualidade usa a primeira medida.
  const times = rows.filter(r => r.method === method).flatMap(r => r.latency_samples.map(Number));
  for (const k of cutoffs) {
    const subset = perQuery.filter(r => r.method === method && r.k === k);
    const binarySubset = subset.filter(r => r.binary_eligible);
    summary.push({
      method, k, queries: subset.length,
      binary_eligible_queries: binarySubset.length,
      binary_excluded_queries: subset.length - binarySubset.length,
      mrr_eligible_queries: binarySubset.length,
      precision_eligible_queries: binarySubset.length,
      recall_eligible_queries: binarySubset.length,
      hit_rate_eligible_queries: binarySubset.length,
      ndcg_eligible_queries: subset.filter(r => r.ndcg !== null).length,
      mrr: mean(binarySubset.map(r => r.rr)),
      precision: mean(binarySubset.map(r => r.precision)),
      recall: mean(binarySubset.map(r => r.recall)),
      ndcg: mean(subset.map(r => r.ndcg)),
      hit_rate: mean(binarySubset.map(r => r.hit_rate)),
      judged_fraction_returned: mean(subset.map(r => r.judged_fraction_returned)),
      unjudged_mean: mean(subset.map(r => r.unjudged)),
      latency_measurements: times.length,
      latency_mean_ms: mean(times),
      latency_p50_ms: percentile(times, .50),
      latency_p95_ms: percentile(times, .95),
    });
  }
}
function csv(data) {
  const columns = Object.keys(data[0]);
  function cell(value) {
    if (value === null || value === undefined) return '';
    let text = typeof value === 'number' ? String(value).replace('.', ',') : String(value);
    if (typeof value === 'string' && /^[=+\-@\t\r]/.test(text)) text = "'" + text;
    return /[;"\r\n]/.test(text) ? '"' + text.replace(/"/g, '""') + '"' : text;
  }
  return '\uFEFF' + columns.join(';') + '\r\n' + data.map(row => columns.map(key => cell(row[key])).join(';')).join('\r\n');
}
function file(data, fileName) { return {data: Buffer.from(csv(data)).toString('base64'), mimeType:'text/csv', fileName}; }
return [{json: {
  experiment_name: config.experiment_name, configuration: config,
  summary, per_query: perQuery,
  report_version: 'binary_exact_eligible_v3',
  binary_metrics_scope: 'Consultas com exact_count > 0, mesmo conjunto elegível do MRR; null significa excluída, não zero.',
  ndcg_scope: 'Consultas com IDCG > 0 (ao menos um Exact ou Partial).',
  latency_query_scope: 'Todas as consultas medidas, excluindo aquecimento.', 
  latency_scope: 'Recuperação + materialização do top-K no PostgreSQL; exclui embedding, rede e escrita.',
}, binary: {
  resumo: file(summary, 'resumo.csv'),
  por_consulta: file(perQuery, 'por_consulta.csv'),
}}];
